import hashlib

chunks, index = [], {}

def backup(data: bytes):
    for i in range(0, len(data), 4):  # fixed 4-byte chunks (toy)
        c = data[i:i+4]
        h = hashlib.md5(c).hexdigest()[:8]
        if h not in index:
            index[h] = c
        chunks.append(h)

backup(b'aaaaBBBBaaaaBBBB')
backup(b'aaaaBBBBccccBBBB')  # mostly duplicate
print('logical chunks: %d, unique stored: %d' % (len(chunks), len(index)))
print('dedup ratio: %.1fx' % (len(chunks) / len(index)))

import hashlib

def H(x):
    return hashlib.sha256(str(x).encode()).hexdigest()[:8]

state = {'a': 1, 'b': 2}
snaps = {}

def snapshot(name):
    snaps[name] = H(sorted(state.items()))  # O(1): just the root hash
    print('snapshot %-8s root=%s' % (name, snaps[name]))

snapshot('s1')
state['c'] = 3   # copy-on-write: new chunks, old snapshot untouched
state['a'] = 99
snapshot('s2')
print('s1 still root=%s (immutable; restore = point at the old root)' % snaps['s1'])

import hashlib

# swarming: fetch chunks from multiple untrusted peers, verify each
peers = {
    'p1': {b'c1': b'data-one'},
    'p2': {b'c2': b'data-two'},
    'evil': {b'c1': b'CORRUPTED'},  # untrusted peer lies...
}
want = {b'c1': hashlib.sha256(b'data-one').hexdigest(),
        b'c2': hashlib.sha256(b'data-two').hexdigest()}

fetched = {}
for cid, expect in want.items():
    for peer, blocks in peers.items():
        if cid in blocks:
            if hashlib.sha256(blocks[cid]).hexdigest() == expect:
                fetched[cid] = blocks[cid]
                break  # verified: the lie was harmless
print('fetched %d/%d chunks (untrusted peers OK: verification is cryptographic)' % (len(fetched), len(want)))
